(1,  'Севилья',       'VL-23/Севилья',       1, '25% Вис, 6% Шерсть, 69% ПЭ',          150, 270, 4.95, NULL, 10, 5, 'Костюмно-плательная ткань с добавлением шерсти. Плотная, хорошо держит форму, не мнётся. Подходит для костюмов, брюк, юбок и жакетов.',                                                   'images/fabrics/Севилья_1.jpg'),
(2,  'Прага',         'VL-23/Прага',         1, '10% Шерсть, 26% Вис, 60% ПЭ, 4% Спан', 150, 270, 4.95, NULL, 10, 5, 'Плотная костюмная ткань с шерстью и спандексом. Тянется, не стесняет движений. Идеальна для деловых костюмов и брюк с посадкой.',                                                       'linear-gradient(145deg, #5A5A6A 0%, #2A2A3A 100%)'),
(3,  'Мадрид',        'VL-22/Мадрид',        1, '40% ХБ, 10% Лавсан, 45% ПЭ, 5% ЭЛ',   150, 240, 5.40, NULL, 10, 5, 'Смесовая костюмная ткань с хлопком и эластаном. Дышащая, комфортная при носке, хорошо держит стрелки и форму изделия.',                                                                   'linear-gradient(145deg, #8A7A6A 0%, #4A3A2A 100%)'),
(4,  'Монако',        'VL-23/Монако',        1, '37% ХБ, 60% ПЭ, 3% ЭЛ',               150, 200, 5.70, NULL, 10, 5, 'Лёгкая костюмная ткань с хлопком. Приятная к телу, дышащая, подходит для летних костюмов и брюк. Хорошо гладится.',                                                                   'linear-gradient(145deg, #4A5A7A 0%, #1A2A4A 100%)'),
(5,  'Палермо',       'VL-23/Палермо',       1, '25% ХБ, 75% ПЭ',                       150, 260, 5.20, NULL, 10, 5, 'Плотная смесовая ткань с устойчивостью к износу. Практичная, не растягивается, хорошо сохраняет форму при длительной носке.',                                                          'linear-gradient(145deg, #7A6A5A 0%, #3A2A1A 100%)'),
(6,  'Токио 0.5',     'VL-23/Токио 0.5',     1, '35% Вис, 63% ПЭ, 2% Спан',             150, 230, 5.40, NULL, 10, 5, 'Костюмная ткань серии Токио с лёгким блеском вискозы. Тянется по вертикали, отлично садится по фигуре. Для платьев и костюмов.',                                                      'linear-gradient(145deg, #6A5A7A 0%, #2A1A4A 100%)'),
(7,  'Токио 1',       'VL-23/Токио 1',       1, '32% Вис, 66% ПЭ, 2% Спан',             150, 210, 5.40, NULL, 10, 5, 'Средняя плотность серии Токио. Лёгкая, приятная к телу, хорошо драпируется. Подходит для офисных платьев и брюк.',                                                                    'linear-gradient(145deg, #7A5A8A 0%, #3A1A4A 100%)'),
(8,  'Токио 1.5',     'VL-23/Токио 1.5',     1, '28% Вис, 70% ПЭ, 2% Спан',             150, 240, 5.40, NULL, 10, 5, 'Плотная версия серии Токио. Держит форму, не просвечивает. Лучший выбор для строгих костюмов и деловых платьев.',                                                                        'linear-gradient(145deg, #5A4A6A 0%, #1A0A2A 100%)'),
(9,  'Элиза',         'VL-23/Элиза',         1, '37% Вис, 60% ПЭ, 3% ЭЛ',               150, 240, 5.00, NULL, 10, 5, 'Элегантная костюмная ткань с добавлением эластана. Приятный матовый блеск, хорошо тянется, комфортна в носке весь день.',                                                              'linear-gradient(145deg, #5A6A7A 0%, #1A2A3A 100%)'),
(10, 'Марсель',       'VL-24/Марсель',       1, '26% Вис, 70% ПЭ, 4% Спан',             150, 230, 5.60, NULL, 10, 5, 'Новинка 2024. Костюмная ткань с повышенным содержанием спандекса. Отличная эластичность, возвращается в форму после растяжения.',                                                       'linear-gradient(145deg, #4A6A6A 0%, #1A3A3A 100%)'),
(11, 'Лондон',        'VL-23/Лондон',        1, '33% Вис, 60% ПЭ, 7% ЭЛ',               150, 240, 5.30, NULL, 10, 5, 'Костюмно-плательная ткань с повышенным эластаном. Максимальный комфорт, тянется во все стороны. Для fitted-силуэтов и облегающих изделий.',                                             'linear-gradient(145deg, #2A3A5A 0%, #0A1A3A 100%)'),
(12, 'Пандора лайт',  'VL-23/Пандора лайт',  1, '18% Вис, 77% ПЭ, 5% ЭЛ',               150, 160, 3.70, NULL, 10, 5, 'Лёгкая версия Пандоры. Тонкая, дышащая, с лёгким блеском. Хороша для летних платьев и блуз. Одна из самых доступных позиций серии.',                                                 'linear-gradient(145deg, #A0A0B0 0%, #606070 100%)'),
(13, 'Пандора',       'VL-23/Пандора',       1, '18% Вис, 77% ПЭ, 5% ЭЛ',               150, 210, 4.40, NULL, 10, 5, 'Классическая Пандора — одна из самых популярных позиций. Средняя плотность, отличная драпировка, широкий выбор расцветок.',                                                            'linear-gradient(145deg, #7A7A8A 0%, #3A3A4A 100%)'),
(14, 'Флоренция',     'VL-24/Флоренция',     1, '32% Вис, 65% ПЭ, 3% Спан',             145, 260, 6.50, NULL, 10, 5, 'Премиальная новинка 2024. Плотная костюмная ткань с мягкой текстурой. Ширина 145 см, отличный выход изделий. Для сезонных коллекций.',                                                'linear-gradient(145deg, #8A5A5A 0%, #4A1A1A 100%)'),
(15, 'Ницца',         'VL-24/Ницца',         1, '33% Вис, 5% Шерсть, 60% ПЭ, 2% Спан',  140, 260, 7.40, NULL, 10, 5, 'Премиальная ткань с натуральной шерстью. Благородный матовый вид, отличная посадка, не скатывается. Для дизайнерских коллекций.',                                                     'linear-gradient(145deg, #6A5A3A 0%, #2A1A0A 100%)'),
(16, 'Alpaka',        'VL-06/Alpaka',        1, '25% Вис, 75% ПЭ',                       150, 175, 4.80, NULL, 10, 5, 'Лёгкая костюмная ткань с нежной текстурой. Матовая поверхность, хорошая драпировка. Универсальная для платьев, блуз и лёгких жакетов.',                                              'linear-gradient(145deg, #C0B090 0%, #806040 100%)'),
(17, 'Лили',          'VL-23/Лили',          1, '90% ПЭ, 10% Спан',                      150, 200, 3.50, NULL, 10, 5, 'Доступная костюмная ткань из полиэстера со спандексом. Практичная, износостойкая, легко стирается. Хороший выбор для массовых коллекций.',                                             'linear-gradient(145deg, #B0A0C0 0%, #605070 100%)'),

