(18, 'ХБ002',         'VL-23/ХБ002',         2, '100% ХБ',                               150, 120, 4.30, NULL, 10, 5, 'Чистый хлопок для рубашек и платьев. Дышащий, гигроскопичный, приятный к коже. Легко обрабатывается, хорошо гладится.',                                                               'linear-gradient(145deg, #F0E8D8 0%, #C0A888 100%)'),
(19, 'ХБ003',         'VL-23/ХБ003',         2, '75% ХБ, 20% ПЭ, 5% ЭЛ',                150, 120, 4.40, NULL, 10, 5, 'Хлопок с добавлением полиэстера и эластана. Не мнётся так сильно как чистый хлопок, тянется. Удобен в носке, практичен в уходе.',                                                     'linear-gradient(145deg, #E8E0D0 0%, #B0A890 100%)'),
(20, 'ХБ004',         'VL-23/ХБ004',         2, '90% ХБ, 10% ЭЛ',                        150, 170, 4.95, NULL, 10, 5, 'Плотный хлопок с эластаном. Более тяжёлый и структурный, чем ХБ002/003. Отлично подходит для рубашек с хорошей посадкой.',                                                           'linear-gradient(145deg, #E0D8C8 0%, #A89878 100%)'),
(21, 'ХБ Принт',      'VL-23/ХБ Принт',      2, '100% Хлопок',                           150, 115, 4.00, NULL, 10, 5, 'Тонкий хлопок с печатным рисунком. Лёгкий, дышащий, яркие принты. Для летних платьев, сарафанов, детской одежды.',                                                                    'linear-gradient(145deg, #F0D8C0 0%, #C09870 100%)'),
(22, 'Belinda Soft',  'VL-06/Belinda Soft',  2, '24% Вис, 71% ПЭ, 5% ЭЛ',               150, 150, 5.30, NULL, 10, 5, 'Мягкая рубашечная ткань с вискозой. Нежная на ощупь, не раздражает кожу. Для блуз, рубашек и платьев-рубашек.',                                                                       'linear-gradient(145deg, #E8EEF8 0%, #A8B8D8 100%)'),
