(32, 'TEN TEN',              'VL-24/TEN TEN',             3, '100% Лиоцелл',               145, 160, 6.60, NULL, 10, 5, 'Лиоцелл (Tencel) — экологичное волокно из древесной целлюлозы. Мягкий, дышащий, антибактериальный. Премиальный выбор для устойчивой моды.',                                          'linear-gradient(145deg, #A8C0B0 0%, #588070 100%)'),
(33, 'Ramie',                'VL-24/Ramie',               3, '100% Крапива',               135,  80, 7.90, NULL, 10, 5, 'Рами — ткань из крапивы. Очень лёгкая (80 г/м²), экологичная, антибактериальная. Уникальный натуральный материал для авторских коллекций.',                                          'linear-gradient(145deg, #C8D8B8 0%, #889870 100%)'),
