(40, 'Японский шёлк',        'VL-23/Японский шелк',       3, '100% ПЭ',                     150, 170, 5.40, NULL, 10, 5, 'Японский шёлк — более плотная имитация натурального шёлка. Шелковистая поверхность, красивый блеск, хорошо шьётся. Для нарядных изделий.',                                         'linear-gradient(145deg, #E8E0D0 0%, #B0A880 100%)'),
(41, 'Японский шёлк принт',  'VL-23/Японский шелк принт', 3, '100% ПЭ',                     150, 150, 5.80, NULL, 10, 5, 'Японский шёлк с печатью. Нарядный вид, лёгкость и блеск в сочетании с принтом. Популярен для вечерних платьев.',                                                                    'linear-gradient(145deg, #D8C8E0 0%, #988090 100%)'),
(42, 'Лион',                 'VL-23/Лион',                3, '95% ПЭ, 5% Метанить',         150, 180, 6.00, NULL, 10, 5, 'Ткань с металлизированной нитью (метанитью). Лёгкое мерцание, торжественный вид. Для праздничных платьев, вечерних нарядов, новогодних коллекций.',                                 'linear-gradient(145deg, #D8C888 0%, #888050 100%)'),
